var n=`1239-griot`;var a=`world-1239`;var t=`HT`;var r=`central-america-caribbean`;var o=4;var s=238;var d={en:`Griot`,ua:`Гріо`};var l={en:`Griot is a dish from Haiti featuring pork shoulder, orange juice, lime juice, garlic. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Гріо, страва кухні країни Гаїті з такими основними складниками: свиняча лопатка, апельсиновий сік, сік лайма, часник. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var g=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 120 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 120 хвилин.`,t:[`marinating`],m:120,i:[[`pork-shoulder`,920,`g`],[`orange-juice`,140,`ml`],[`lime-juice`,80,`ml`],[`garlic`,6,`clove`],[`ground-cloves`,3,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 100 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 100 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:100,i:[[`water`,850,`ml`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 14 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 14 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:14,i:[[`canola-oil`,780,`ml`]]},{en:`Arrange the fully cooked and prepared parts of the dish on plates or in the intended serving vessel, adding the listed toppings or accompaniments just before serving.`,ua:`Зберіть повністю приготовані частини страви на тарілках або в посуді для подавання, додавши зазначені топінги та доповнення безпосередньо перед подаванням.`,t:[`layered-assembly`,`garnishing`],m:4,i:[[`white-cabbage`,220,`g`],[`carrot`,130,`g`],[`white-vinegar`,55,`ml`]]}];var u={slug:n,id:a,country:`HT`,region:r,servings:4,minutes:238,title:d,text:l,steps:g};export{t as country,u as default,a as id,s as minutes,r as region,o as servings,n as slug,g as steps,l as text,d as title};